<?php if ($quotations === []): ?><p class="empty"><?= e(__('empty.quotations')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.number')) ?></th><th><?= e(__('fields.status')) ?></th><th><?= e(__('fields.total')) ?></th></tr></thead><tbody><?php foreach ($quotations as $row): ?><tr><td data-label="Number"><a href="<?= e(url('/portal/quotations/' . $row['id'])) ?>"><?= e($row['number']) ?></a></td><td data-label="Status"><?= e($row['status']) ?></td><td data-label="Total"><?= e(money($row['total'], $row['currency'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
